function installNov2(){
 if(AUDIT_DATE!=='2026-11-02')return;
 document.querySelector('.board-nav').insertAdjacentHTML('beforeend','<a href="#rescue">04 · 救人复盘</a><a href="#shield">05 · 打盾复盘</a>');
 document.querySelector('footer').insertAdjacentHTML('beforebegin','<section id="rescue"><div class="chapter"><span>04</span><h2>救人复盘</h2><p>只列恐惧行军正常点名后，明确没有救出且在复盘截止前死亡的记录。成功解救、结束中断和漏断恐惧后的重新附身不列。</p></div><div id="nov2RescueResults"></div></section><section id="shield"><div class="chapter"><span>05</span><h2>打盾复盘</h2><p>11把实际出现P2盾，共17个盾窗。柱状图统计盾期间对Boss的破盾吸收量，含宠物，不含血量伤害。爆发区分施放、覆盖与未见记录，不代表当时CD可用或应该施放。</p></div><div id="nov2ShieldResults"></div></section>');
 document.getElementById('interruptSummaryResults').insertAdjacentHTML('beforebegin','<div id="nov2InterruptResults"></div>');
}
function nov2Groups(items){const groups=new Map();for(const x of items){if(!groups.has(x.fight))groups.set(x.fight,[]);groups.get(x.fight).push(x);}return [...groups];}
function nov2ResultClass(text){return text.includes('成功')||text==='打断正常'?'nov2-ok':text.includes('失败')||text.includes('漏断')?'nov2-fail':'nov2-neutral';}
function renderNov2Record(x,label){const html=renderRecord(x,label);return x.evidenceText?html.replace('</article>',`<details class="nov2-evidence"><summary>查看证据</summary><p>${prose(x.evidenceText)}</p></details></article>`):html;}
function nov2ShieldDeaths(x){const rows=x.deathsDuringRecords||[];const early=rows.filter(r=>!r.afterCutoff),late=rows.filter(r=>r.afterCutoff),after=x.deathsAfterRecords||[];const list=rs=>rs.map(r=>person(r.name)+' '+esc(r.time)).join('；');return `<p class="nov2-deaths"><strong>截止前盾内死亡：</strong>${early.length?list(early):'无'}</p>${late.length?`<p class="nov2-deaths nov2-death-late"><strong>复盘截止后死亡（仅列事实）：</strong>${list(late)}</p>`:''}${after.length?`<details class="nov2-deaths nov2-after-deaths"><summary>窗口结束后10秒内死亡（不计盾内）</summary><p>${list(after)}${after.some(r=>r.afterCutoff)?'；其中复盘截止后的记录仅列事实。':''}</p></details>`:''}`;}
function renderNov2(){
 const gs=DATA.ghosts.filter(accepts),rs=DATA.resonance.filter(accepts);
 $('ghostResults').innerHTML=gs.map(x=>renderNov2Record(x,'本人鬼接触')).join('')||empty();
 $('resonanceResults').innerHTML=rs.map(x=>renderRecord(x,'恶毒共鸣')).join('')||empty();
 const circles=(DATA.circleTableRows||[]).filter(accepts);
 $('circleResults').innerHTML=nov2Groups(circles).map(([fid,rows])=>`<article class="fight nov2-circle-fight">${head(rows[0],'套圈结果')}<div class="nov2-table-scroll"><table class="nov2-table"><thead><tr><th>轮次</th><th>点名</th><th>爆炸</th><th>结果</th><th>点名玩家</th></tr></thead><tbody>${rows.map(x=>`<tr data-circle="${x.key}"><th>第${x.round}轮</th><td>${esc(x.mark)}</td><td>${esc(x.explode)}</td><td class="${nov2ResultClass(x.status)}">${esc(x.status)}</td><td>${x.players.map(person).join('、')}</td></tr>${x.detail?`<tr class="nov2-exception"><td colspan="5"><details class="nov2-exception-copy nov2-circle-detail"><summary>失败复盘</summary><p>${prose(x.detail)}</p></details></td></tr>`:''}`).join('')}</tbody></table></div></article>`).join('')||empty();
 const groups=DATA.interrupts.readGroups.filter(accepts);
 for(const id of ['interruptSummaryResults','interruptCounts','interrupt-all','interrupt-melee','interrupt-ranged','interrupt-unknown','interruptSharedTitle','interruptSharedResults'])if($(id))$(id).hidden=true;
 document.querySelector('.interrupt-tabs').hidden=true;
 $('nov2InterruptResults').innerHTML=nov2Groups(groups).map(([fid,rows])=>`<article class="fight nov2-interrupt-fight">${head(rows[0],'每波大怪打断')}<div class="nov2-table-scroll"><table class="nov2-table nov2-interrupt-table"><thead><tr><th>波次</th><th>大怪</th><th>结果</th><th>读条顺序</th></tr></thead><tbody>${rows.map(g=>`<tr><th>第${g.wave}波</th><td>${esc(g.label)}</td><td class="${nov2ResultClass(g.status)}">${esc(g.status)}</td><td><details class="nov2-read-details"><summary>查看顺序</summary><ol>${g.reads.map(r=>`<li>第${r.ordinal}条 · ${esc(r.start)}–${esc(r.end||'未结算')} · ${r.actualNames.length?r.actualNames.map(person).join('、'):r.result==='cast_success'?'漏断':r.result==='npc_died_without_observed_interrupt_or_completion'?'大怪死亡，读条中止':'未结算'}</li>`).join('')}</ol>${g.pendingReason?`<p>${esc(g.pendingReason)}</p>`:''}</details></td></tr>${g.problem?`<tr class="nov2-exception"><td colspan="4"><div class="nov2-exception-copy"><strong>漏断复盘：</strong>${prose(g.detail)}${g.pendingReason?`<p>${esc(g.pendingReason)}</p>`:''}</div></td></tr>`:''}`).join('')}</tbody></table></div></article>`).join('')||empty();
 $('nov2RescueResults').innerHTML=(DATA.rescueFailures||[]).filter(accepts).map(x=>renderRecord(x,'未救出')).join('')||'<p class="empty">当前筛选范围没有明确未救出的正常点名记录。</p>';
 const filter=state();
 $('nov2ShieldResults').innerHTML=(DATA.shieldReviews||[]).filter(accepts).map(x=>{
  const max=Math.max(1,...x.rows.map(r=>r.damage));const rows=filter.player?x.rows.filter(r=>r.name===filter.player):x.rows;
  return `<article class="fight nov2-shield">${head(x,`P2第${x.shield}盾`)}<h3>${esc(x.start)}–${esc(x.end)}</h3><p class="${x.afterCutoff?'nov2-neutral':x.state.startsWith('已破盾')?'nov2-ok':'nov2-fail'}">${esc(x.state)}</p>${nov2ShieldDeaths(x)}<p class="nov2-unit">盾期间对Boss的破盾吸收量 · 单位：万 · 含宠物，不含血量伤害${filter.player?' · 名次按全体DPS计算':''}</p><div class="nov2-bars">${rows.map(r=>`<div class="nov2-bar-row"><div class="nov2-bar-top"><span>${r.rank}. ${person(r.name)}</span><strong>${(r.damage/10000).toFixed(2)}万</strong></div><div class="nov2-bar-track"><span style="width:${(r.damage/max*100).toFixed(3)}%;background:${COLORS[r.className]||'#64748b'}"></span></div><p class="nov2-burst">${esc(r.status.replace('本盾未见已核实技能施放或覆盖','未见关键爆发记录'))}${r.state?' · '+esc(r.state):''}</p><details class="nov2-cd-details"><summary>爆发记录</summary>${r.details.length?r.details.map(t=>`<p>${esc(t.replace('Shadow Dance','暗影之舞'))}</p>`).join(''):'<p>本盾未见已核实关键技能的施放或覆盖；不推断CD可用或应该交。</p>'}</details></div>`).join('')||'<p class="empty">该玩家不在本盾DPS排行中。</p>'}</div></article>`;
 }).join('')||'<p class="empty">当前筛选范围没有实际出现的P2盾。</p>';
 $('filterState').textContent=`当前查看：${AUDIT_DATES[AUDIT_DATE].label} · ${filter.fid?title(filter.fid):'全部场次'} · ${filter.player||'全部玩家'}${filter.q?' · “'+filter.q+'”':''}`;
 $('playerFilter').style.color=COLORS[DATA.roster[filter.player]]||'#1d2939';
}
